    fun getPortraitUrl(heroName: String): String {
        val normalized = normalizeHeroKey(heroName)
        return portraitByHeroLower[normalized]?.first
            ?: portraitByHeroLower.entries.firstOrNull { normalized.contains(it.key) || it.key.contains(normalized) }?.value?.first
            ?: ""
    }

    fun getFallbackPortraitUrl(heroName: String): String {
        val normalized = normalizeHeroKey(heroName)
        return portraitByHeroLower[normalized]?.second
            ?: portraitByHeroLower.entries.firstOrNull { normalized.contains(it.key) || it.key.contains(normalized) }?.value?.second
            ?: getPortraitUrl(heroName)
    }

    fun hasHeroPortrait(heroName: String): Boolean {
        return getPortraitUrl(heroName).isNotEmpty()
    }

    fun resolveHeroPortrait(heroName: String, candidateUrl: String = ""): String {
        val canonical = getPortraitUrl(heroName)
        if (canonical.isNotEmpty()) return canonical
        return candidateUrl.trim()
    }

    fun resolveHeroFallback(heroName: String, candidateFallbackUrl: String = ""): String {
        val canonicalFallback = getFallbackPortraitUrl(heroName)
        if (canonicalFallback.isNotEmpty()) return canonicalFallback
        return candidateFallbackUrl.trim()
    }

    private fun normalizeHeroKey(heroName: String): String {
        return heroName.trim().lowercase()
            .replace(".", "")
            .replace("-", " ")
            .replace(Regex("\\s+"), " ")
    }
}
